// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount <= address(this).balance);
        vm.deal(address(c), amount);

        vm.prank(caller);
        bool ok;
        try c.withdrawAll(caller) { ok = true; } catch { ok = false; }

        assertTrue(!ok || caller == address(this));
    }
}
